请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-014

=== 用户原始指令 (query.txt) ===
想搞个深色舞台风的物流总览卡,整体氛围背景,不用图纯文字配深色块,信息分三组用分隔线分开(已签收/派送中/待取件),文案基本是固定的几个字段,带天气读取显示当前城市温度,下面一个跳时钟设置取件闹钟的按钮,已签收的区块用绿色块做正向标识,不要任何渐变,能滚动。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想搞个深色舞台风的物流总览卡,整体氛围背景,不用图纯文字配深色块,信息分三组用分隔线分开(已签收/派送中/待取件),文案基本是固定的几个字段,带天气读取显示当前城市温度,下面一个跳时钟设置取件闹钟的按钮,已签收的区块用绿色块做正向标识,不要任何渐变,能滚动。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "当前天气查询的区县名称",
            "sampleValue": "南山"
          },
          "prefectureName": {
            "type": "string",
            "description": "当前天气查询的城市名称",
            "sampleValue": "深圳"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "天气能力加载状态",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": []
}

